export function combatLobby(d){const g=d.g,arena=d.style==='arena';return g.heading('ARÈNE POKÉWORLD','Combats de dresseurs','Deux façons de combattre. Une même équipe, toute ta stratégie.')+`<div class="combat-mode-choice" role="group" aria-label="Style de combat"><button data-act="combat-style" data-style="classic" class="${arena?'':'selected'}"><span>01 · LA STRATÉGIE AU TOUR PAR TOUR</span><b>Classique</b><p>Choisis ta capacité, pose tes protections et prépare le bon changement de Pokémon.</p><i>Types · Statuts · Talents · Priorités</i></button><button data-act="combat-style" data-style="arena" class="${arena?'selected':''}"><span>02 · L’ACTION EN TEMPS RÉEL</span><b>Arène 2D</b><p>Déplace-toi, vise, esquive les attaques et utilise les obstacles du terrain.</p><i>Déplacements · Quatre capacités · Esquives</i></button></div>${arena?`<section class="arena-configuration"><div class="arena-stage-options">${[['grass','Prairie'],['dirt','Terre battue'],['ruins','Dalles anciennes'],['cavern','Caverne']].map(([id,name])=>`<button data-act="arena-stage" data-stage="${id}" class="${g.state.settings.arenaTheme===id?'selected':''}"><canvas width="190" height="112" data-arena-preview="${id}"></canvas><b>${name}</b></button>`).join('')}</div><div class="arena-formats"><span>Format du combat</span><button data-act="arena-format" data-format="duel" class="${g.state.settings.arenaFormat!=='squad'?'selected':''}">Duel · 1 actif</button><button data-act="arena-format" data-format="squad" class="${g.state.settings.arenaFormat==='squad'?'selected':''}">Escouade · jusqu’à 3 actifs</button><small>Six Pokémon par équipe. Les partenaires de l’escouade sont assistés par l’IA ; tu peux prendre leur contrôle.</small></div></section>`:''}<div class="combat-rule-note"><b>${arena?'Temps réel':'Tour par tour'} · Équipes de six · Niveau 50 en duel</b><span>${arena?'ZQSD / flèches · 1–4 capacités · Espace esquive · Joystick sur mobile':'Statuts, variations de statistiques, soins, météo et effets de terrain'}</span></div><div class="friends-grid"><section class="panel"><span class="eyebrow">PRENDS TES MARQUES</span><h2>${arena?'Entre dans l’arène':'Affûte ta stratégie'}</h2><p>Entraîne-toi contre un dresseur IA avec ton équipe actuelle de ${g.state.team.length} Pokémon.</p><button class="primary" data-act="${arena?'arena-solo':'start-battle'}">Affronter l’IA ${arena?'en arène':'en classique'} ↗</button><button class="text-button" data-act="route" data-page="team">Préparer mon équipe →</button></section><section class="panel"><span class="eyebrow">DUEL ENTRE AMIS</span><h2>Défie un dresseur</h2><p>Six Pokémon par joueur, au niveau 50. Les IV, EV, natures et talents de ta collection comptent.</p><button class="primary" data-act="duel-create">Créer ${arena?'une arène':'un duel'}</button>${d.peer?.id&&!d.searching?`<div class="room-code"><small>CODE DU ${arena?'MATCH':'DUEL'}</small><strong>${g.escape(d.peer.id)}</strong><button data-act="duel-copy">Copier le code</button></div>`:''}<input id="duel-code" placeholder="Code du duel de ton ami" aria-label="Code du duel"><button data-act="duel-join">Rejoindre</button></section><section class="panel"><span class="eyebrow">RENCONTRES EN LIGNE</span><h2>Un nouvel adversaire</h2><p>La file te met en relation avec un véritable joueur dans le même mode.</p><button class="primary" data-act="duel-search" ${d.searching?'disabled':''}>${d.searching?'Recherche en cours…':'Chercher un adversaire'}</button>${d.searching?'<button data-act="duel-cancel">Annuler la recherche</button>':''}<p class="network-status">${g.escape(d.status)}</p><p class="muted">Duels amicaux. Le site est privé : ton adversaire doit aussi y avoir accès.</p></section></div>`}
